package com.saludintegral.medico.exception;
import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import java.util.*;import java.time.*;@RestControllerAdvice public class ApiExceptionHandler{@ExceptionHandler(NoSuchElementException.class)ResponseEntity<?> nf(Exception e){return ResponseEntity.status(404).body(Map.of("timestamp",Instant.now().toString(),"status",404,"error","Not Found","mensaje",e.getMessage()));}@ExceptionHandler(MethodArgumentNotValidException.class)ResponseEntity<?> val(MethodArgumentNotValidException e){Map<String,String>m=new LinkedHashMap<>();e.getBindingResult().getFieldErrors().forEach(x->m.put(x.getField(),x.getDefaultMessage()));return ResponseEntity.badRequest().body(Map.of("timestamp",Instant.now().toString(),"status",400,"error","Bad Request","detalles",m));}@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<?> bad(Exception e){return ResponseEntity.badRequest().body(Map.of("status",400,"error","Bad Request","mensaje",e.getMessage()));}@ExceptionHandler(IllegalStateException.class)ResponseEntity<?> dep(Exception e){return ResponseEntity.status(503).body(Map.of("status",503,"error","Service Unavailable","mensaje",e.getMessage()));}@ExceptionHandler(Exception.class)ResponseEntity<?> err(Exception e){return ResponseEntity.internalServerError().body(Map.of("status",500,"error","Internal Server Error","mensaje","Error interno del servicio"));}}
